class Solution {
    public int[] getConcatenation(int[] nums){
        int[] answer=new int[nums.length*2];
        for(int i=0;i<nums.length;i++)answer[i]=answer[i+nums.length]=nums[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getConcatenation(nums:IntArray):IntArray{
        val answer=IntArray(nums.size*2);
        for(i in nums.indices){
            answer[i]=nums[i];
            answer[i+nums.size]=nums[i]
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<int> getConcatenation(vector<int>& nums){
        vector<int> answer=nums;
        answer.insert(answer.end(),nums.begin(),nums.end());
        return answer;
    }
};
